<template><view class="page"><view class="content"><view class="tabs"><view v-for="(t,i) in tabs" :key="t" class="tab" :class="{on:tab===i}" @click="tab=i">{{t}}</view></view><view class="title-row tools"><view class="sub">已选择 {{selected.length}} 项</view><view><text @click="toast('游客名单已导出')">导出名单</text><text @click="toast('已打开旅行社分配')">批量分配</text></view></view><view class="card order" v-for="o in filtered" :key="o.id"><view class="order-top"><checkbox :checked="selected.includes(o.id)" color="#12a594" @click="select(o.id)"/><view class="list-main"><b>{{o.title}}</b><view class="sub">{{o.id}} · {{o.time}}</view></view><text class="tag" :class="{'tag-orange':o.type==='积分兑换'}">{{o.type}}</text></view><view class="order-data"><view><text>申请人</text><b>{{o.user}}</b></view><view><text>出行日期</text><b>{{o.date}}</b></view><view><text>旅行社</text><b>{{o.agency||'待分配'}}</b></view></view><view class="divider"/><view class="order-actions"><view class="btn reject" @click="review(o,'驳回')">驳回</view><view class="btn approve" @click="review(o,'通过')">审核通过</view></view></view></view></view></template><script setup>import{ref,computed}from'vue';const tab=ref(0),selected=ref([]);const tabs=['待审核','已通过','已驳回'];const orders=ref([{id:'TS20260621008',title:'泰山经典游 2天1夜',type:'积分兑换',time:'06-21 14:32',user:'林晓雨',date:'2026-07-06',agency:'齐鲁文旅',status:0},{id:'DZ20260621016',title:'川西雪山深度定制',type:'人工定制',time:'06-21 13:08',user:'陈泽宇',date:'2026-08-12',agency:'',status:0},{id:'TS20260620071',title:'泰山经典游 2天1夜',type:'积分兑换',time:'06-20 18:43',user:'周然',date:'2026-07-13',agency:'齐鲁文旅',status:0}]);const filtered=computed(()=>orders.value.filter(o=>o.status===tab.value));const select=id=>selected.value.includes(id)?selected.value.splice(selected.value.indexOf(id),1):selected.value.push(id);const review=(o,a)=>{o.status=a==='通过'?1:2;uni.showToast({title:`已${a}`,icon:'success'})};const toast=title=>uni.showToast({title,icon:'none'})</script><style scoped>.tools{margin:25rpx 0}.tools>view:last-child{display:flex;gap:25rpx;color:#12a594}.order-top{display:flex;align-items:center;gap:15rpx}.order-data{display:grid;grid-template-columns:repeat(3,1fr);background:#f4f6f4;border-radius:18rpx;padding:20rpx;margin-top:20rpx}.order-data text,.order-data b{display:block;font-size:22rpx}.order-data text{color:#778684;margin-bottom:8rpx}.order-actions{display:flex;justify-content:flex-end;gap:15rpx}.order-actions .btn{height:64rpx;padding:0 25rpx}.reject{background:#fff1e9;color:#ff7a35}.approve{background:#12a594;color:#fff}</style>
